sources.routing.cod:
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Metric;
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" score;
symbol from "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" @bias;
effect @bias <- 1;
proc inner(x::Metric)->i64 { score(x) + @bias }
symbol @task::proc(Metric)->i64;
effect @task <- inner;
proc routed(x::Metric)->i64 { behave @task(x) }
proc direct(x::Metric)->i64 { inner(x) }
export inner; export routed; export direct; export @task;

