sources.entry.cod:
using symbol "std:io" @print;
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Sample;
using "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" Metric;
symbol from "/ws/EvtWorks/cod-project/tests/cod/language/method-view-library.cod" @bias;
using "routing.cod" direct as frozen_direct;
using "routing.cod" routed as frozen_route;
using "adapter.cod" direct as adapted_direct;
using "adapter.cod" routed as adapted_route;
using "adapter.cod" selected;
symbol from "routing.cod" @task;
symbol @frozen::proc(Metric)->i64, @adapted::proc(Metric)->i64, @selected::proc(Metric)->i64;
effect @frozen <- frozen_route;
effect @adapted <- adapted_route;
effect @selected <- selected;
effect @task <- selected;
effect @bias <- 5;
symbol @arena::region;
effect @arena <- region(4096u64);
{
 let sample = create(@arena);
 behave @print(frozen_direct(sample));
 behave @print(adapted_direct(sample));
 behave @print(perform @frozen(sample));
 behave @print(perform @adapted(sample));
 behave @print(behave @frozen(sample));
 behave @print(behave @adapted(sample));
 behave @print(perform @selected(sample));
 behave @print(@bias);
};
